        "quote": "晚饭后：吃"
      },
      {
        "event_id": "lite_evt_00452",
        "explanation": "The doctor gave a concrete follow-up owner/path and timing window.",
        "quote": "请务必在几天内完成复诊"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00031",
